#!/usr/bin/env bash
# Applies: multi-select "Which National Collection" on the Debtors page,
# matching the existing Month(s) multi-select pattern used for Rectory.
#
# Touches:
#   client/src/pages/Debtors.jsx   (UI: multi-select + per-collection columns)
#   src/graphql/typeDefs.js        (adds collectionNames: [String!] to debtors query)
#   src/graphql/resolvers.js       (filters debtors by collectionNames, ANY match)
#
# Run this from the ROOT of your diocesan-finance-api checkout.

set -euo pipefail

if [ ! -f package.json ] || [ ! -d client ]; then
  echo "Error: run this from the root of the diocesan-finance-api repo (package.json and client/ not found here)."
  exit 1
fi

PATCH_B64=""

echo "$PATCH_B64" | base64 -d > /tmp/national-collections-multiselect.patch

echo "Applying patch..."
git apply --check /tmp/national-collections-multiselect.patch 2>/tmp/patch-check-err.txt || {
  echo "Patch does not apply cleanly against your current files. This usually means"
  echo "Debtors.jsx / typeDefs.js / resolvers.js have diverged from the version this was generated against."
  cat /tmp/patch-check-err.txt
  exit 1
}

git apply /tmp/national-collections-multiselect.patch
rm -f /tmp/national-collections-multiselect.patch

echo "Done. Modified files:"
echo "  - client/src/pages/Debtors.jsx"
echo "  - src/graphql/typeDefs.js"
echo "  - src/graphql/resolvers.js"
echo ""
echo "Review with: git diff"
echo "Then commit: git add -A && git commit -m 'Allow multi-select for National Collections on Debtors page'"
